_NATIONS = ("Englishman", "Spaniard", "Ukrainian", "Norwegian", "Japanese")


def _solve():
    pos = range(5)

    def next_to(a, b):
        return abs(a - b) == 1

    orderings = list(permutations(pos))
    for red, green, ivory, yellow, blue in (
        o for o in orderings if o[1] == o[2] + 1
    ):
        for eng, spa, ukr, nor, jap in (
            o for o in orderings if o[3] == 0 and o[0] == red and next_to(o[3], blue)
        ):
            for coffee, tea, milk, juice, water in (
                o for o in orderings
                if o[2] == 2 and o[0] == green and o[1] == ukr
            ):
                for dog, snail, fox, horse, zebra in (
                    o for o in orderings if o[0] == spa
                ):
                    for dance, paint, read, football, chess in (
                        o for o in orderings
                        if o[1] == yellow and o[4] == jap
                        and o[3] == juice
                        and o[0] == snail
                    ):
                        if next_to(read, fox) and next_to(paint, horse):
                            owners = dict(zip(_NATIONS, (eng, spa, ukr, nor, jap)))
                            by_house = {v: k for k, v in owners.items()}
                            return by_house[water], by_house[zebra]


def drinks_water():
    return _solve()[0]


def owns_zebra():
    return _solve()[1]
